From 5128662cae8ec1e72733a6c392d0b565972a3a3b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:21:11 +0100
Subject: [PATCH] WirelessSetting: add the mesh mode

WirelessSetting only knew the infrastructure, ad-hoc and access point
modes, so an 802.11s mesh connection was read as infrastructure and was
saved back that way. Add a Mesh mode that maps to NetworkManager's mesh.

BUG: 502159
---
 src/settings/wirelesssetting.cpp | 8 ++++++++
 src/settings/wirelesssetting.h   | 2 ++
 2 files changed, 10 insertions(+)

diff --git a/src/settings/wirelesssetting.cpp b/src/settings/wirelesssetting.cpp
index cdce75c..00a5822 100644
--- a/src/settings/wirelesssetting.cpp
+++ b/src/settings/wirelesssetting.cpp
@@ -13,6 +13,10 @@
 #define NM_SETTING_WIRELESS_SEC "security"
 #define NM_SETTING_WIRELESS_ASSIGNED_MAC_ADDRESS "assigned-mac-address"

+#if !NM_CHECK_VERSION(1, 20, 0)
+#define NM_SETTING_WIRELESS_MODE_MESH "mesh"
+#endif
+
 #include <QDebug>

 NetworkManager::WirelessSettingPrivate::WirelessSettingPrivate()
@@ -337,6 +341,8 @@ void NetworkManager::WirelessSetting::fromMap(const QVariantMap &setting)
             setMode(Adhoc);
         } else if (mode == QLatin1String(NM_SETTING_WIRELESS_MODE_AP)) {
             setMode(Ap);
+        } else if (mode == QLatin1String(NM_SETTING_WIRELESS_MODE_MESH)) {
+            setMode(Mesh);
         }
     }

@@ -425,6 +431,8 @@ QVariantMap NetworkManager::WirelessSetting::toMap() const
         setting.insert(QLatin1String(NM_SETTING_WIRELESS_MODE), QLatin1String(NM_SETTING_WIRELESS_MODE_ADHOC));
     } else if (mode() == Ap) {
         setting.insert(QLatin1String(NM_SETTING_WIRELESS_MODE), QLatin1String(NM_SETTING_WIRELESS_MODE_AP));
+    } else if (mode() == Mesh) {
+        setting.insert(QLatin1String(NM_SETTING_WIRELESS_MODE), QLatin1String(NM_SETTING_WIRELESS_MODE_MESH));
     }

     if (band() != Automatic) {
diff --git a/src/settings/wirelesssetting.h b/src/settings/wirelesssetting.h
index 6ca51bd..6139f03 100644
--- a/src/settings/wirelesssetting.h
+++ b/src/settings/wirelesssetting.h
@@ -41,11 +41,13 @@ public:
      * \value Infrastructure
      * \value Adhoc
      * \value Ap
+     * \value[since 6.33] Mesh
      */
     enum NetworkMode {
         Infrastructure,
         Adhoc,
         Ap,
+        Mesh,
     };

     /*!
